<style>
:root{--bg:#0d1320;--surface:#111c2d;--surface2:#1a2638;--surface3:#0f1928;--border:#263854;--text:#f8fafc;--muted:#91a4bf;--dim:#68809f;--accent:#3b82f6;--good:#10b981;--warn:#f59e0b;--bad:#ef4444;--radius:16px;--radius-sm:10px}*{box-sizing:border-box}body{margin:0;font-family:Inter,Arial,sans-serif;background:var(--bg);color:var(--text)}.layout{display:flex;min-height:100vh}.main{flex:1;padding:28px;min-width:0;background:radial-gradient(circle at top right,rgba(59,130,246,.08),transparent 38%),var(--bg)}.wrap{max-width:1380px;margin:0 auto}.top{display:flex;justify-content:space-between;align-items:flex-start;gap:18px;margin-bottom:22px}.title{font-size:2rem;font-weight:900;margin:0}.subtitle{color:var(--muted);line-height:1.6;margin:8px 0 0}.card{background:var(--surface);border:1px solid var(--border);border-radius:var(--radius);padding:20px;margin-bottom:16px}.card h2,.card h3{margin-top:0}.grid{display:grid;gap:14px}.grid-2{grid-template-columns:repeat(2,minmax(0,1fr))}.grid-3{grid-template-columns:repeat(3,minmax(0,1fr))}.field label{display:block;color:var(--dim);font-size:.75rem;font-weight:800;text-transform:uppercase;letter-spacing:.06em;margin-bottom:7px}.input,.select,.textarea{width:100%;background:var(--surface3);border:1px solid var(--border);color:var(--text);border-radius:10px;padding:11px 12px;font:inherit}.textarea{min-height:95px;resize:vertical}.input:focus,.select:focus,.textarea:focus{outline:2px solid rgba(59,130,246,.35);border-color:var(--accent)}.btn{display:inline-flex;align-items:center;justify-content:center;gap:7px;border:1px solid transparent;border-radius:10px;padding:10px 14px;font-weight:800;text-decoration:none;cursor:pointer;background:var(--accent);color:#fff}.btn.secondary{background:var(--surface2);border-color:var(--border);color:var(--text)}.btn.good{background:var(--good)}.btn.warn{background:var(--warn);color:#111827}.btn.bad{background:var(--bad)}.btn.disabled{opacity:.5;cursor:not-allowed;pointer-events:none}.actions{display:flex;gap:9px;flex-wrap:wrap;align-items:center}.badge{display:inline-flex;align-items:center;padding:5px 9px;border-radius:999px;border:1px solid var(--border);background:var(--surface2);font-size:.74rem;font-weight:800}.badge.good{color:#a7f3d0;border-color:rgba(16,185,129,.45);background:rgba(16,185,129,.08)}.badge.warn{color:#fde68a;border-color:rgba(245,158,11,.45);background:rgba(245,158,11,.08)}.badge.bad{color:#fecaca;border-color:rgba(239,68,68,.45);background:rgba(239,68,68,.08)}.muted{color:var(--muted)}.dim{color:var(--dim)}.alert{padding:13px 15px;border-radius:12px;margin-bottom:16px;border:1px solid rgba(16,185,129,.35);background:rgba(16,185,129,.10);color:#a7f3d0}.alert.error{border-color:rgba(239,68,68,.35);background:rgba(239,68,68,.10);color:#fecaca}.alert.warn{border-color:rgba(245,158,11,.35);background:rgba(245,158,11,.10);color:#fde68a}.metric{background:var(--surface2);border:1px solid var(--border);border-radius:13px;padding:15px}.metric strong{font-size:1.55rem;display:block}.metric span{display:block;margin-top:3px;color:var(--muted);font-size:.85rem}.table-wrap{overflow:auto}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:11px 12px;border-bottom:1px solid var(--border);text-align:left;vertical-align:middle}.table th{color:var(--dim);font-size:.72rem;text-transform:uppercase;letter-spacing:.04em}.table tbody tr:hover{background:rgba(255,255,255,.018)}.table .number-input{width:82px;text-align:center}.help{border:1px solid var(--border);border-radius:12px;background:var(--surface3);padding:12px 14px}.help summary{cursor:pointer;font-weight:800}.help p{color:var(--muted);line-height:1.55}.wizard{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;margin-bottom:20px}.wizard-step{display:flex;align-items:center;gap:10px;background:var(--surface);border:1px solid var(--border);border-radius:13px;padding:13px}.wizard-step .num{width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:var(--surface2);font-weight:900;color:var(--muted)}.wizard-step strong{display:block;font-size:.88rem}.wizard-step span{display:block;color:var(--muted);font-size:.72rem;margin-top:2px}.wizard-step.active{border-color:rgba(59,130,246,.65);box-shadow:0 0 0 1px rgba(59,130,246,.12)}.wizard-step.active .num{background:var(--accent);color:white}.wizard-step.done .num{background:var(--good);color:white}.section-title{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:14px}.section-title h2,.section-title h3{margin:0}.status-panel{display:flex;align-items:center;justify-content:space-between;gap:14px;border-radius:13px;padding:14px 16px;background:var(--surface2);border:1px solid var(--border)}.status-panel strong{display:block;margin-bottom:4px}.status-panel.good{border-color:rgba(16,185,129,.4)}.status-panel.warn{border-color:rgba(245,158,11,.4)}.status-panel.bad{border-color:rgba(239,68,68,.4)}.kicker{font-size:.74rem;text-transform:uppercase;letter-spacing:.08em;color:var(--dim);font-weight:900}.plain-list{margin:0;padding-left:20px;color:var(--muted);line-height:1.8}.definition-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:12px}.definition{background:var(--surface3);border:1px solid var(--border);border-radius:10px;padding:12px}.definition strong{display:block;margin-bottom:5px}.definition span{font-size:.8rem;color:var(--muted);line-height:1.45}.progress-line{height:8px;border-radius:999px;background:var(--surface3);overflow:hidden;border:1px solid var(--border)}.progress-line>span{display:block;height:100%;background:var(--accent);border-radius:999px}.pagination{margin-top:16px}.review-row{display:flex;justify-content:space-between;gap:20px;padding:11px 0;border-bottom:1px solid var(--border)}.review-row:last-child{border-bottom:0}.review-row span:first-child{color:var(--muted)}.callout{border-left:3px solid var(--accent);padding:12px 14px;background:rgba(59,130,246,.08);border-radius:0 10px 10px 0;color:var(--muted);line-height:1.6}.footer-actions{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-top:18px}.small{font-size:.82rem}.weight-cell{min-width:90px}.nowrap{white-space:nowrap}@media(max-width:1000px){.grid-2,.grid-3,.definition-grid{grid-template-columns:1fr 1fr}.main{padding:18px}.top{flex-direction:column}}@media(max-width:720px){.layout{display:block}.wizard{grid-template-columns:1fr}.grid-2,.grid-3,.definition-grid{grid-template-columns:1fr}.table th,.table td{padding:9px 8px}.title{font-size:1.55rem}}
</style>
